RSpec.describe "timekeeping:alerts reference_unavailable attribution" do
  include ActiveSupport::Testing::TimeHelpers

  before(:all) do
    Rails.application.load_tasks if Rake::Task.tasks.empty?
  end

  around do |example|
    env_before = ENV.to_h.slice("TIMEKEEPING_BASE_URL", "TIMEKEEPING_SERVICE_TOKEN")
    ENV["TIMEKEEPING_BASE_URL"] = "http://timekeeping.alerts.test"
    ENV["TIMEKEEPING_SERVICE_TOKEN"] = "service-token-alerts-tenant"
    travel_to(Time.utc(2026, 3, 3, 12, 7)) { example.run }
  ensure
    %w[TIMEKEEPING_BASE_URL TIMEKEEPING_SERVICE_TOKEN].each { |key| ENV[key] = env_before[key] }
  end

  def tenant_alert_window(writes:, reference_unavailable:)
    { "window_start" => "2026-03-03T12:00:00Z", "writes" => writes, "reference_unavailable" => reference_unavailable,
      "latency_ms_sum" => (writes + reference_unavailable) * 10,
      "latency_ms_buckets" => { "25" => writes + reference_unavailable } }
  end

  it "logs the reference_unavailable alert only under the company whose own completed window is over 1%" do
    TimekeepingOwnership.ensure_initial!
    failing_company = 7101
    healthy_company = 7102
    # Pooled, the two companies give 3 / 2000 = 0.15%, under 1%; only the
    # per-company rate (3 / 100 = 3%) is over it.
    body = {
      "window_seconds" => 300,
      "latency_bucket_bounds_ms" => [25, 50, 100, 200, 300, 500, 1000, 2500, 5000],
      "overflow_bucket" => "inf",
      "total_field" => "writes + reference_unavailable",
      "companies" => [
        { "company_id" => failing_company, "windows" => [tenant_alert_window(writes: 97, reference_unavailable: 3)] },
        { "company_id" => healthy_company, "windows" => [tenant_alert_window(writes: 1900, reference_unavailable: 0)] }
      ],
      "outbox_lag" => []
    }
    stub_request(:get, "http://timekeeping.alerts.test/internal/v1/metrics")
      .with(headers: { "Authorization" => "Bearer service-token-alerts-tenant" })
      .to_return(status: 200, body: JSON.generate(body), headers: { "Content-Type" => "application/json" })

    Rake::Task["timekeeping:alerts"].reenable
    captured = StringIO.new
    original_stdout = $stdout
    begin
      $stdout = captured
      Rake::Task["timekeeping:alerts"].invoke
    ensure
      $stdout = original_stdout
    end

    # "It logs each alert with `company_id`." and "`503 reference_unavailable` over 1% of writes for 5 minutes;"
    lines = captured.string.lines
    alert_lines = lines.select { |line| line.include?("reference_unavailable") && line.include?("company_id=") }
    expect(alert_lines.size).to eq(1)
    expect(alert_lines.first).to include("company_id=#{failing_company}")
    expect(lines.grep(/company_id=#{healthy_company}\b/)).to be_empty
  end
end

