RSpec.describe "timekeeping:alerts outbox lag per company" do
  it "logs the outbox lag alert only under the company whose own oldest unsent row is over 5 minutes" do
    Rails.application.load_tasks if Rake::Task.tasks.empty?
    Rake::Task["timekeeping:alerts"].reenable
    TimekeepingOwnership.current.update!(owner: "timekeeping")
    service_token = "service-#{SecureRandom.hex(24)}"
    metrics_body = {
      "window_seconds" => 300,
      "latency_bucket_bounds_ms" => [25, 50, 100, 200, 300, 500, 1000, 2500, 5000],
      "overflow_bucket" => "inf",
      "total_field" => "writes + reference_unavailable",
      "companies" => [],
      "outbox_lag" => [
        { "company_id" => 101, "oldest_unsent_age_seconds" => 301 },
        { "company_id" => 202, "oldest_unsent_age_seconds" => 120 }
      ]
    }
    stub_request(:get, "http://timekeeping.test/internal/v1/metrics")
      .with(headers: { "Authorization" => "Bearer #{service_token}" })
      .to_return(status: 200, body: JSON.generate(metrics_body), headers: { "Content-Type" => "application/json" })

    env_before = ENV.to_h.slice("TIMEKEEPING_BASE_URL", "TIMEKEEPING_SERVICE_TOKEN")
    captured = StringIO.new
    original_stdout = $stdout
    begin
      ENV["TIMEKEEPING_BASE_URL"] = "http://timekeeping.test"
      ENV["TIMEKEEPING_SERVICE_TOKEN"] = service_token
      $stdout = captured
      Rake::Task["timekeeping:alerts"].invoke
    ensure
      $stdout = original_stdout
      %w[TIMEKEEPING_BASE_URL TIMEKEEPING_SERVICE_TOKEN].each { |key| ENV[key] = env_before[key] }
    end

    # "It logs each alert with `company_id`." The rule is "outbox lag (oldest
    # unsent row age) of the current owner over 5 minutes", judged per company:
    # company 202's two-minute lag must neither alert nor borrow 101's age.
    lines = captured.string.lines
    expect(lines.grep(/company_id=101\b/)).not_to be_empty
    expect(lines.grep(/company_id=202\b/)).to be_empty
  end
end
